(() => {
'use strict';
const $=id=>document.getElementById(id), sky=$('sky'), plane=$('plane'), clouds=[...document.querySelectorAll('.cloud')];
let started=false,busy=false,visited=new Set(),drag=null,moved=false,muted=false,ctx=null,flightTimer=null,round=0;
try{muted=localStorage.getItem('littleHandsMuted')==='true'}catch{}
function syncSound(){$('sound').setAttribute('aria-pressed',String(muted));$('sound').setAttribute('aria-label',muted?'打开声音':'关闭声音')}
function tone(done=false){if(muted)return;try{ctx??=new(window.AudioContext||window.webkitAudioContext)();ctx.resume();[0,1,2].slice(0,done?3:2).forEach((v)=>{const o=ctx.createOscillator(),g=ctx.createGain();o.type='sine';o.frequency.value=[523.25,659.25,783.99][v];g.gain.setValueAtTime(0,ctx.currentTime+v*.16);g.gain.linearRampToValueAtTime(.055,ctx.currentTime+v*.16+.02);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+v*.16+.4);o.connect(g);g.connect(ctx.destination);o.start(ctx.currentTime+v*.16);o.stop(ctx.currentTime+v*.16+.41)})}catch{}}
function speak(text){if(muted||!('speechSynthesis'in window))return;window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='zh-CN';u.rate=.85;window.speechSynthesis.speak(u)}
function position(x,y){plane.style.left=x+'%';plane.style.top=y+'%'}
function center(c){const r=sky.getBoundingClientRect(),a=c.getBoundingClientRect();return{x:(a.left+a.width/2-r.left)/r.width*100,y:(a.top+a.height/2-r.top)/r.height*100}}
function hint(){clouds.forEach(c=>c.classList.remove('target'));const c=clouds.find((_,i)=>!visited.has(i));if(!c){$('hand').hidden=true;return}c.classList.add('target');const p=center(c);$('hand').style.left=`${p.x}%`;$('hand').style.top=`${p.y+7}%`;$('hand').hidden=false}
function visit(i){if(!started||busy||visited.size===3)return;if(visited.has(i)){tone();return}busy=true;$('hand').hidden=true;const p=center(clouds[i]);position(p.x,p.y+3);const current=round;flightTimer=setTimeout(()=>{if(current!==round)return;visited.add(i);clouds[i].classList.add('visited');document.querySelectorAll('.cloud-dots i')[i].classList.add('done');tone(visited.size===3);busy=false;if(visited.size===3){sky.classList.add('finished');$('rainbow').classList.add('show');$('again').hidden=false;$('status').textContent='云朵送你一条彩虹。';speak('哇，彩虹出来啦！');position(50,40)}else{$('status').textContent='云朵里，藏着暖暖的小太阳。';hint()}},850)}
function reset(){round++;clearTimeout(flightTimer);busy=false;drag=null;plane.classList.remove('dragging');visited.clear();clouds.forEach(c=>c.classList.remove('visited','target'));document.querySelectorAll('.cloud-dots i').forEach(i=>i.classList.remove('done'));sky.classList.remove('finished');$('rainbow').classList.remove('show');$('again').hidden=true;position(50,74);$('status').textContent='去云朵里，找一找惊喜。';if(started)hint()}
$('start').addEventListener('click',()=>{started=true;$('intro').hidden=true;clouds.forEach(c=>c.disabled=false);plane.disabled=false;reset();tone();speak('点点云朵，和小飞机一起飞。')});
$('sound').addEventListener('click',()=>{muted=!muted;try{localStorage.setItem('littleHandsMuted',String(muted))}catch{}syncSound();if(muted){if('speechSynthesis'in window)window.speechSynthesis.cancel();ctx?.suspend().catch(()=>{})}if(!muted)tone()});
clouds.forEach((c,i)=>{c.disabled=true;c.addEventListener('click',()=>visit(i))});plane.disabled=true;
plane.addEventListener('click',()=>{if(moved){moved=false;return}const i=clouds.findIndex((_,i)=>!visited.has(i));if(i>=0)visit(i)});
plane.addEventListener('pointerdown',e=>{if(!started||busy||visited.size===3||drag!==null)return;drag={id:e.pointerId,x:e.clientX,y:e.clientY};moved=false;plane.setPointerCapture(e.pointerId)});
plane.addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId)return;if(Math.hypot(e.clientX-drag.x,e.clientY-drag.y)<8&&!moved)return;moved=true;plane.classList.add('dragging');$('hand').hidden=true;const r=sky.getBoundingClientRect();position(Math.max(14,Math.min(86,(e.clientX-r.left)/r.width*100)),Math.max(12,Math.min(84,(e.clientY-r.top)/r.height*100)))});
function endDrag(e,cancel=false){if(!drag||drag.id!==e.pointerId)return;drag=null;plane.classList.remove('dragging');if(!moved)return;if(!cancel){let nearest=-1,dist=Infinity;clouds.forEach((c,i)=>{if(visited.has(i))return;const r=c.getBoundingClientRect(),d=Math.hypot((e.clientX-r.left-r.width/2)/r.width,(e.clientY-r.top-r.height/2)/r.height);if(d<dist){dist=d;nearest=i}});if(nearest>=0&&dist<.9){visit(nearest);return}}position(50,74);hint()}
plane.addEventListener('pointerup',e=>endDrag(e));plane.addEventListener('pointercancel',e=>endDrag(e,true));
$('again').addEventListener('click',()=>{reset();tone()});$('reset').addEventListener('click',()=>{reset();if(started)tone()});window.addEventListener('resize',()=>{if(started&&!busy)hint()});document.addEventListener('visibilitychange',()=>{if(document.hidden&&'speechSynthesis'in window)window.speechSynthesis.cancel()});window.addEventListener('pagehide',()=>{clearTimeout(flightTimer);if('speechSynthesis'in window)window.speechSynthesis.cancel()});syncSound();$('hand').hidden=true;
})();
